const char *sober_bionic_libc_backend(void)
{
    return g_glibc ? "native glibc + Bionic version nodes" : "glibc unavailable";
}
unsigned sober_bionic_libc_symbol_count(void) { return 411u; }

/* Self-initialising: the guest may call these symbols as soon as it is
 * mapped, so resolve glibc targets from a loader constructor. */
__attribute__((constructor)) static void sober_bionic_libc_ctor(void)
{
    sober_bionic_libc_install();
}

